INSERT INTO public.quest_test_cases(quest_id, case_index, stdin, expected_stdout, is_sample)
SELECT q.id, s.case_index, s.stdin, s.expected_stdout, s.is_sample
FROM seeded s JOIN public.quests q ON q.slug = s.slug
ON CONFLICT (quest_id, case_index) DO UPDATE SET
  stdin = EXCLUDED.stdin, expected_stdout = EXCLUDED.expected_stdout, is_sample = EXCLUDED.is_sample;

DO $$
DECLARE v_count INTEGER;
BEGIN
  SELECT count(*) INTO v_count FROM public.quests WHERE is_system_seed;
  IF v_count < 320 THEN
    RAISE EXCEPTION 'CodeBox seed incomplete: expected at least 320 system quests, found %', v_count;
  END IF;
END $$;

COMMIT;
